  `url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `relatedUrl` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
