) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `aowow_spawns` (
  `guid` int(11) NOT NULL COMMENT '< 0: vehicle accessory',
